#include "../Source/Processor.h"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <memory>
void check(bool ok,const char* message){if(!ok){std::cerr<<message<<'\n';std::exit(1);}}void set(Processor& p,const char* id,float value){auto* parameter=p.state.getParameter(id);check(parameter,"missing parameter");parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
int main(){for(double rate:{44100.,48000.,96000.,192000.}){auto legacy=std::make_unique<Processor>(),extreme=std::make_unique<Processor>();for(auto* p:{legacy.get(),extreme.get()}){set(*p,"eqPresent",0);set(*p,"limPresent",0);set(*p,"stabilizerPresent",1);set(*p,"stabilizerOn",1);set(*p,"stabilizerAmount",100);set(*p,"stabilizerSpeed",0);set(*p,"stabilizerTame",0);p->setRateAndBufferSizeDetails(rate,257);p->prepareToPlay(rate,257);check(p->getLatencySamples()==static_cast<int>(std::ceil(rate*.005)),"Stabilizer intensity changed PDC");}set(*extreme,"stabilizerIntensity",3);juce::AudioBuffer<float> a(2,257),b(2,257);juce::MidiBuffer midi;double difference=0,reference=0;for(int block=0;block<static_cast<int>(rate*3/257);++block){for(int i=0;i<257;++i){const double t=(block*257+i)/rate;const float value=.2f*std::sin(6.283185307179586*125*t)+.12f*std::sin(6.283185307179586*700*t)+.05f*std::cos(6.283185307179586*7000*t);a.setSample(0,i,value);a.setSample(1,i,value*.9f);}b.makeCopyOf(a);legacy->processBlock(a,midi);extreme->processBlock(b,midi);if(block>rate/257)for(int c=0;c<2;++c)for(int i=0;i<257;++i){const double delta=a.getSample(c,i)-b.getSample(c,i);difference+=delta*delta;reference+=static_cast<double>(a.getSample(c,i))*a.getSample(c,i);}}check(10*std::log10(difference/reference)>-25,"APVTS Stabilizer intensity does not reach DSP output");juce::MemoryBlock state;extreme->getStateInformation(state);Processor restored;restored.setStateInformation(state.getData(),static_cast<int>(state.getSize()));check(restored.state.getRawParameterValue("stabilizerIntensity")->load()==3,"Phase 2C state did not restore");}std::cout<<"Passed: Phase 2C APVTS, output, state and PDC at four rates\n";}
